function WA({items:n,type:i,onPlayClick:l,onInfoClick:r}){
  const[curr,setCurr]=M.useState(0);
  const heroList=(n&&n.length>0)?n:DF_HERO;
  const count=heroList.length;
  const item=heroList[curr]||heroList[0];

  M.useEffect(()=>{
    if(count<=1)return;
    const timer=setInterval(()=>{
      setCurr(prev=>(prev+1)%count);
    },6000);
    return()=>clearInterval(timer);
  },[count]);

  const handlePrev=()=>setCurr(prev=>(prev-1+count)%count);
  const handleNext=()=>setCurr(prev=>(prev+1)%count);

  if(!item)return null;

  const bgUrl=item.backdrop_path
    ?`/api/image-proxy?size=original&path=${item.backdrop_path}`
    :(item.poster_path?`/api/image-proxy?size=original&path=${item.poster_path}`:"");
  const title=item.title||item.name||"";
  const overview=item.overview||"";
  const mediaType=item.media_type||i||"movie";
  const rating=item.vote_average?item.vote_average.toFixed(1):"7.5";
  const year=(item.release_date||item.first_air_date||"2026").substring(0,4);
  const formattedIndex=String(curr+1).padStart(2,"0");
  const formattedTotal=String(count).padStart(2,"0");

  return d.jsxs("div",{
    className:"hero-multimovies-wrapper",
    children:[
      d.jsx("img",{
        key:item.id||curr,
        src:bgUrl,
        alt:title,
        className:"hero-backdrop-image"
      }),
      d.jsx("div",{className:"hero-overlay-dark-left"}),
      d.jsx("div",{className:"hero-overlay-dark-bottom"}),
      d.jsx("div",{className:"hero-overlay-dark-top"}),
      d.jsxs("div",{
        className:"hero-content-left",
        children:[
          d.jsxs("div",{
            className:"hero-kicker-bar",
            children:[
              d.jsx("span",{className:"hero-kicker-line"}),
              d.jsx("span",{className:"hero-kicker-text",children:"SPOTLIGHT / FEATURED"})
            ]
          }),
          d.jsx("h1",{
            className:"hero-main-title",
            children:title
          }),
          d.jsxs("div",{
            className:"hero-metadata-row",
            children:[
              d.jsxs("span",{className:"text-yellow-400 font-bold",children:["★ ",rating]}),
              d.jsx("span",{children:year}),
              d.jsx("span",{className:"uppercase px-2 py-0.5 rounded bg-white/10 text-xs font-semibold",children:mediaType}),
              d.jsx("span",{className:"px-2 py-0.5 rounded bg-red-900/60 text-red-300 border border-red-700/50 text-xs font-mono font-bold",children:"4K ULTRA HD"})
            ]
          }),
          overview&&d.jsx("p",{
            className:"hero-overview-desc",
            children:overview
          }),
          d.jsxs("div",{
            className:"hero-actions-row",
            children:[
              d.jsxs("button",{
                onClick:()=>l&&l(item.id,mediaType),
                className:"hero-btn-watch",
                children:[d.jsx(Gf,{size:18,fill:"currentColor"}),"Watch now"]
              }),
              d.jsxs("button",{
                onClick:()=>r&&r(item.id,mediaType),
                className:"hero-btn-info",
                children:[d.jsx(Ay,{size:18}),"More info"]
              }),
              d.jsx("button",{
                onClick:()=>r&&r(item.id,mediaType),
                className:"hero-btn-add",
                title:"Add to list",
                children:d.jsx(Pr,{size:18})
              })
            ]
          }),
          d.jsxs("div",{
            className:"hero-pagination-bar",
            children:[
              d.jsxs("div",{
                className:"flex items-baseline gap-1",
                children:[
                  d.jsx("span",{className:"hero-count-active",children:formattedIndex}),
                  d.jsx("span",{className:"hero-count-total",children:` / ${formattedTotal}`})
                ]
              }),
              d.jsx("div",{
                className:"hero-dash-container",
                children:heroList.map((_,idx)=>d.jsx("button",{
                  key:idx,
                  onClick:()=>setCurr(idx),
                  className:idx===curr?"hero-dash-active":"hero-dash-inactive",
                  "aria-label":`Go to slide ${idx+1}`
                }))
              }),
              d.jsxs("div",{
                className:"flex items-center gap-2 ml-2",
                children:[
                  d.jsx("button",{
                    onClick:handlePrev,
                    className:"hero-arrow-btn",
                    title:"Previous",
                    children:d.jsx(jy,{size:16})
                  }),
                  d.jsx("button",{
                    onClick:handleNext,
                    className:"hero-arrow-btn",
                    title:"Next",
                    children:d.jsx(Cy,{size:16})
                  })
                ]
              })
            ]
          })
        ]
      })
    ]
  });
}









